from __future__ import annotations

"""Fail-closed contract for every Agent installer generated by WebAdmin.

The contract is created from the staged payload before packaging and embedded in
that payload.  WebAdmin may publish an artifact as READY only when the payload,
version, upgrade/repair and platform service contracts all pass.

This module intentionally uses only the Python standard library so it can be
used by the catalog and Windows EXE packager without introducing dependency
cycles.
"""

import hashlib
import io
import json
import re
import struct
import tarfile
import zipfile
from pathlib import Path
from typing import Any, Iterable

SCHEMA = "gideon-agent-installer-contract/v2"
STATUS_PASS = "PASS"

COMMON_REQUIRED = (
    "gideon_agent.py",
    "gideon_reverse_tunnel.py",
    "gideon_agent_http.py",
    "gideon_agent_security.py",
    "gideon_agent_worker.py",
    "gideon_agent_job_contract.py",
    "gideon_agent_connectivity.py",
    "gideon_agent_archive.py",
    "gideon_agent_component.py",
    "gideon_agent_vlc_offline.py",
    "gideon_agent_vlc_offline_control.py",
    "gideon_agent_config.py",
    "requirements-agent.txt",
    "agent.template.json",
    "runtime.contract.json",
    "configure-agent.py",
    "gideon_common/__init__.py",
)

PLATFORM_REQUIRED = {
    "windows": (
        "gideon-agent-setup.ps1",
        "gideon-agent-uninstall.ps1",
    ),
    "linux": (
        "gideon-agent-setup",
        "gideon-agent-first-run-native",
        "gideon-agent-first-run-launch",
        # The optional Player is a separate, explicit local-admin pilot.  The
        # launcher is required so a generated Linux/Raspberry package cannot
        # carry the Player runtime without its safe non-root desktop boundary.
        "gideon-agent-player-launch",
    ),
    "darwin": (
        "gideon-agent-setup",
        "gideon-agent-first-run-native",
    ),
}

# Linux playback is deliberately split from the privileged Agent service.  The
# local graphical companion is started only through the root-owned launcher
# and receives access solely to the signed public exchange/runtime ACL.  This
# declaration travels inside every generated installer so a release cannot
# silently claim the Player boundary while packaging it differently.
#
# Do not change the main Agent service to ``User=gideonagent`` as part of this
# contract.  The existing service owns enrollment material, signed jobs,
# transfer staging and reverse-tunnel state as one transaction.  Moving that
# service to a less-privileged identity needs a separate migration that splits
# those state paths and proves upgrade/rollback compatibility first.
LINUX_PLAYER_PACKAGE_SECURITY = {
    "code_tree_owner": "root:root",
    "code_tree_write": "root-only",
    "venv_owner": "root:root",
    "launcher_owner": "root:root",
    "agent_state_owner": "root:root",
    "desktop_runtime_access": "narrow-acl-public-runtime-only",
    "main_service_user": "unchanged-pending-separate-migration",
}

REPAIR_MARKERS = {
    "windows": (
        "ORPHAN_DETECTED",
        "ORPHAN_REPAIR",
        "ORPHAN_CONFIG_MIGRATION",
        "agent.runtime.json",
        "FINAL_ACCEPTANCE PASS",
        "SERVICE_STAGE",
        "DEGRADED_CONNECTIVITY",
        "VISIBLE_FAILURE_DIAGNOSTIC",
        "PRE_GUI_VALIDATION FAILED",
        "REMOTE_ACCESS_UNSUPPORTED_CONTINUE",
        "PACKAGE_GATEWAY_AUTHORITY",
        "GATEWAY_MIGRATION_REENROLL",
    ),
    "linux": (
        "ORPHAN_DETECTED",
        "ORPHAN_REPAIR",
        "ORPHAN_CONFIG_MIGRATION",
        "agent.runtime.json",
        "FINAL_ACCEPTANCE PASS",
        "systemctl",
        "DEGRADED_CONNECTIVITY",
        "PACKAGE_GATEWAY_AUTHORITY",
        "GATEWAY_MIGRATION_REENROLL",
    ),
    "darwin": (
        "ORPHAN_DETECTED",
        "ORPHAN_REPAIR",
        "ORPHAN_CONFIG_MIGRATION",
        "agent.runtime.json",
        "FINAL_ACCEPTANCE PASS",
        "launchctl",
        "DEGRADED_CONNECTIVITY",
        "PACKAGE_GATEWAY_AUTHORITY",
        "GATEWAY_MIGRATION_REENROLL",
    ),
}

SENSITIVE_NAME_TOKENS = ("secret", "password", "token", "enrollment", "private")
EXE_OVERLAY_MAGIC = b"GIDEON_AGENT_SFX_TRAILER_V1"
EXE_OVERLAY_SCAN_BYTES = 1024 * 1024


def _sha256(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _runtime_version(path: Path) -> str:
    text = Path(path).read_text(encoding="utf-8-sig")
    m = re.search(r'(?m)^VERSION\s*=\s*["\']([^"\']+)["\']\s*$', text)
    if not m:
        raise RuntimeError("INSTALLER_CONTRACT_AGENT_VERSION_MISSING")
    return m.group(1).strip()


def _json(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(Path(path).read_text(encoding="utf-8-sig"))
    except Exception as exc:
        raise RuntimeError(f"INSTALLER_CONTRACT_JSON_INVALID:{Path(path).name}:{exc}") from exc
    if not isinstance(value, dict):
        raise RuntimeError(f"INSTALLER_CONTRACT_JSON_OBJECT_REQUIRED:{Path(path).name}")
    return value


def _normalize_platform(platform_name: str) -> str:
    p = str(platform_name or "").strip().lower()
    if p in {"win32", "win64", "windows"}:
        return "windows"
    if p in {"mac", "macos", "osx", "darwin"}:
        return "darwin"
    if p == "linux":
        return "linux"
    raise RuntimeError(f"INSTALLER_CONTRACT_PLATFORM_UNSUPPORTED:{platform_name}")


def _safe_required_hashes(payload: Path, required: Iterable[str]) -> dict[str, str]:
    result: dict[str, str] = {}
    for rel in required:
        lower = rel.casefold()
        if any(token in lower for token in SENSITIVE_NAME_TOKENS):
            continue
        path = payload / rel
        result[rel] = _sha256(path)
    return result


def write_installer_contract(
    payload: Path,
    *,
    target_id: str,
    platform_name: str,
    architecture: str,
    version: str,
    package_type: str,
    extra_required: Iterable[str] = (),
) -> dict[str, Any]:
    payload = Path(payload).resolve()
    platform_key = _normalize_platform(platform_name)
    expected = str(version or "").strip()
    if not expected:
        raise RuntimeError("INSTALLER_CONTRACT_VERSION_EMPTY")

    required = list(dict.fromkeys(
        list(COMMON_REQUIRED) + list(PLATFORM_REQUIRED[platform_key]) + [str(x) for x in extra_required]
    ))
    missing = [rel for rel in required if not (payload / rel).is_file()]
    if missing:
        raise RuntimeError("INSTALLER_CONTRACT_REQUIRED_FILE_MISSING:" + ",".join(missing))

    agent_version = _runtime_version(payload / "gideon_agent.py")
    template = _json(payload / "agent.template.json")
    runtime_contract = _json(payload / "runtime.contract.json")
    template_version = str(template.get("agent_version") or "").strip()
    runtime_contract_version = str(runtime_contract.get("agent_version") or "").strip()

    versions = {
        "requested": expected,
        "agent_runtime": agent_version,
        "agent_template": template_version,
        "runtime_contract": runtime_contract_version,
    }
    bad_versions = {k: v for k, v in versions.items() if v != expected}
    if bad_versions:
        raise RuntimeError("INSTALLER_CONTRACT_VERSION_MISMATCH:" + json.dumps(bad_versions, sort_keys=True))

    cp = template.get("control_plane") if isinstance(template.get("control_plane"), dict) else {}
    gateway = str(cp.get("base_url") or "").strip()
    if not gateway.lower().startswith("https://"):
        raise RuntimeError("INSTALLER_CONTRACT_GATEWAY_NOT_HTTPS")

    setup_rel = "gideon-agent-setup.ps1" if platform_key == "windows" else "gideon-agent-setup"
    setup_text = (payload / setup_rel).read_text(encoding="utf-8-sig", errors="replace")
    missing_markers = [m for m in REPAIR_MARKERS[platform_key] if m not in setup_text]
    if missing_markers:
        raise RuntimeError("INSTALLER_CONTRACT_REPAIR_MARKER_MISSING:" + ",".join(missing_markers))

    service_model = {
        "windows": "windows-scm-service",
        "linux": "systemd",
        "darwin": "launchd",
    }[platform_key]
    remote_access = {
        "windows": "windows-rdp-loopback",
        "linux": "xrdp-loopback",
        "darwin": "apple-vnc-loopback",
    }[platform_key]

    checks = [
        "payload-required-files",
        "version-coherence",
        "upgrade-detection",
        "orphan-repair",
        "runtime-identity-recovery",
        "native-service-repair",
        "gateway-selftest",
        "remote-access-capability-detection",
        "final-acceptance",
        "visible-failure-diagnostics",
    ]
    doc: dict[str, Any] = {
        "schema": SCHEMA,
        "status": STATUS_PASS,
        "target_id": str(target_id),
        "platform": platform_key,
        "architecture": str(architecture),
        "package_type": str(package_type),
        "agent_version": expected,
        "service_model": service_model,
        "remote_access": remote_access,
        "remote_access_policy": {
            "required_when_supported": True,
            "unsupported_capability_is_non_fatal": True,
            "windows_home_core_behavior": "install-agent-disable-remote-desktop-no-third-party-fallback",
        },
        "identity_policy": {
            "same_site_valid_identity": "preserve-agentid-token",
            "same_site_runtime_identity_only": "recover-agentid-token-from-runtime",
            "same_site_invalid_token": "preserve-agentid-reenroll-token",
            "different_site": "new-enrollment-new-identity",
        },
        "upgrade_policy": {
            "old_or_partial_install": "backup-migrate-replace-runtime-repair-service",
            "corrupt_config_runtime_valid": "rebuild-current-config-recover-runtime-identity",
            "success_requires_target_version": True,
            "success_requires_native_service_running": True,
            "success_requires_final_acceptance": True,
        },
        "versions": versions,
        "required_files": required,
        "required_file_sha256": _safe_required_hashes(payload, required),
        "checks": checks,
    }
    if platform_key == "linux":
        doc["linux_player_package_security"] = dict(LINUX_PLAYER_PACKAGE_SECURITY)
    target = payload / "installer.contract.json"
    target.write_text(json.dumps(doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return doc


def verify_installer_contract(
    payload: Path,
    *,
    expected_version: str,
    expected_target_id: str | None = None,
) -> dict[str, Any]:
    payload = Path(payload).resolve()
    contract_path = payload / "installer.contract.json"
    if not contract_path.is_file():
        raise RuntimeError("INSTALLER_CONTRACT_FILE_MISSING")
    doc = _json(contract_path)
    if str(doc.get("schema") or "") != SCHEMA:
        raise RuntimeError("INSTALLER_CONTRACT_SCHEMA_MISMATCH")
    if str(doc.get("status") or "") != STATUS_PASS:
        raise RuntimeError("INSTALLER_CONTRACT_STATUS_NOT_PASS")
    if str(doc.get("agent_version") or "") != str(expected_version):
        raise RuntimeError("INSTALLER_CONTRACT_EXPECTED_VERSION_MISMATCH")
    if expected_target_id and str(doc.get("target_id") or "") != str(expected_target_id):
        raise RuntimeError("INSTALLER_CONTRACT_TARGET_MISMATCH")
    if str(doc.get("platform") or "") == "linux" and doc.get("linux_player_package_security") != LINUX_PLAYER_PACKAGE_SECURITY:
        raise RuntimeError("INSTALLER_CONTRACT_LINUX_PLAYER_SECURITY_MISMATCH")

    required = [str(x) for x in doc.get("required_files") or []]
    missing = [rel for rel in required if not (payload / rel).is_file()]
    if missing:
        raise RuntimeError("INSTALLER_CONTRACT_VERIFY_FILE_MISSING:" + ",".join(missing))
    for rel, expected in (doc.get("required_file_sha256") or {}).items():
        path = payload / str(rel)
        actual = _sha256(path)
        if actual.casefold() != str(expected).casefold():
            raise RuntimeError(f"INSTALLER_CONTRACT_HASH_MISMATCH:{rel}")

    # Re-evaluate version coherence, not only the serialized declaration.
    agent_version = _runtime_version(payload / "gideon_agent.py")
    template_version = str(_json(payload / "agent.template.json").get("agent_version") or "")
    runtime_version = str(_json(payload / "runtime.contract.json").get("agent_version") or "")
    if {agent_version, template_version, runtime_version} != {str(expected_version)}:
        raise RuntimeError("INSTALLER_CONTRACT_VERIFY_VERSION_MISMATCH")

    result = dict(doc)
    result["contract_sha256"] = _sha256(contract_path)
    result["verified"] = True
    return result


def _tar_has_contract(artifact: Path, expected_contract_sha256: str) -> bool:
    try:
        with tarfile.open(artifact, "r:*") as tar:
            members = [m for m in tar.getmembers() if m.isfile() and m.name.endswith("installer.contract.json")]
            for member in members:
                fh = tar.extractfile(member)
                if fh is None:
                    continue
                data = fh.read()
                if hashlib.sha256(data).hexdigest().casefold() == expected_contract_sha256.casefold():
                    return True
    except Exception:
        return False
    return False


def _deb_has_contract(artifact: Path, expected_contract_sha256: str) -> bool:
    """Read the ar container and verify installer.contract.json in data.tar.*."""
    try:
        data = Path(artifact).read_bytes()
        if not data.startswith(b"!<arch>\n"):
            return False
        offset = 8
        while offset + 60 <= len(data):
            header = data[offset:offset + 60]
            if header[58:60] != b"`\n":
                return False
            name = header[0:16].decode("ascii", "replace").strip().rstrip("/")
            try:
                size = int(header[48:58].decode("ascii", "replace").strip() or "0")
            except ValueError:
                return False
            start = offset + 60
            end = start + size
            if end > len(data):
                return False
            if name.startswith("data.tar"):
                payload = io.BytesIO(data[start:end])
                try:
                    with tarfile.open(fileobj=payload, mode="r:*") as tar:
                        for member in tar.getmembers():
                            if not member.isfile() or not member.name.endswith("installer.contract.json"):
                                continue
                            fh = tar.extractfile(member)
                            if fh is None:
                                continue
                            raw = fh.read()
                            if hashlib.sha256(raw).hexdigest().casefold() == expected_contract_sha256.casefold():
                                return True
                except Exception:
                    return False
            offset = end + (size % 2)
    except Exception:
        return False
    return False


def _exe_overlay_has_contract(artifact: Path, expected_contract_sha256: str) -> bool | None:
    """Validate the GIDEON SFX overlay; return None for legacy resource-based EXEs."""
    try:
        size = Path(artifact).stat().st_size
        scan_length = min(size, EXE_OVERLAY_SCAN_BYTES)
        with Path(artifact).open("rb") as fh:
            fh.seek(size - scan_length)
            tail = fh.read(scan_length)
            marker_offset = tail.rfind(EXE_OVERLAY_MAGIC)
            if marker_offset < 0:
                return None

            trailer_end = size - scan_length + marker_offset + len(EXE_OVERLAY_MAGIC)
            trailer_size = 16 + 64 + 64 + len(EXE_OVERLAY_MAGIC)
            trailer_start = trailer_end - trailer_size
            if trailer_start <= 0:
                return False
            fh.seek(trailer_start)
            trailer = fh.read(trailer_size)
            if len(trailer) != trailer_size or not trailer.endswith(EXE_OVERLAY_MAGIC):
                return False

            payload_length, bootstrap_length = struct.unpack("<QQ", trailer[:16])
            overlay_start = trailer_start - payload_length - bootstrap_length
            if payload_length <= 0 or bootstrap_length <= 0 or overlay_start < 1024:
                return False

            expected_payload_hash = trailer[16:80].decode("ascii")
            expected_bootstrap_hash = trailer[80:144].decode("ascii")
            if not re.fullmatch(r"[0-9a-f]{64}", expected_payload_hash):
                return False
            if not re.fullmatch(r"[0-9a-f]{64}", expected_bootstrap_hash):
                return False

            fh.seek(overlay_start)
            payload_zip = fh.read(payload_length)
            bootstrap = fh.read(bootstrap_length)
            if len(payload_zip) != payload_length or len(bootstrap) != bootstrap_length:
                return False
            if hashlib.sha256(payload_zip).hexdigest() != expected_payload_hash:
                return False
            if hashlib.sha256(bootstrap).hexdigest() != expected_bootstrap_hash:
                return False

        with zipfile.ZipFile(io.BytesIO(payload_zip), "r") as archive:
            try:
                contract = archive.read("installer.contract.json")
            except KeyError:
                return False
        return hashlib.sha256(contract).hexdigest().casefold() == expected_contract_sha256.casefold()
    except Exception:
        return False


def verify_artifact_sanity(
    artifact: Path,
    *,
    package_type: str,
    expected_version: str,
    expected_contract_sha256: str,
    require_exe_embedded_contract: bool = False,
) -> dict[str, Any]:
    artifact = Path(artifact).resolve()
    if not artifact.is_file():
        raise RuntimeError("INSTALLER_ARTIFACT_MISSING")
    size = artifact.stat().st_size
    if size < 1024:
        raise RuntimeError("INSTALLER_ARTIFACT_TOO_SMALL")

    ptype = str(package_type or "").lower()
    with artifact.open("rb") as fh:
        header = fh.read(8)
    embedded_contract = False
    if ptype == "exe":
        if not header.startswith(b"MZ"):
            raise RuntimeError("INSTALLER_ARTIFACT_EXE_MAGIC_INVALID")
        overlay_contract = _exe_overlay_has_contract(artifact, expected_contract_sha256)
        if overlay_contract is False:
            raise RuntimeError("INSTALLER_ARTIFACT_EXE_OVERLAY_INVALID")
        if require_exe_embedded_contract and overlay_contract is not True:
            raise RuntimeError("INSTALLER_ARTIFACT_EXE_CONTRACT_MISSING")
        embedded_contract = overlay_contract is True
    elif ptype == "deb":
        if header != b"!<arch>\n":
            raise RuntimeError("INSTALLER_ARTIFACT_DEB_MAGIC_INVALID")
        embedded_contract = _deb_has_contract(artifact, expected_contract_sha256)
        if not embedded_contract:
            raise RuntimeError("INSTALLER_ARTIFACT_DEB_CONTRACT_MISSING")
    elif ptype == "rpm":
        if header[:4] != bytes.fromhex("edabeedb"):
            raise RuntimeError("INSTALLER_ARTIFACT_RPM_MAGIC_INVALID")
    elif ptype == "tar.gz":
        embedded_contract = _tar_has_contract(artifact, expected_contract_sha256)
        if not embedded_contract:
            raise RuntimeError("INSTALLER_ARTIFACT_TAR_CONTRACT_MISSING")
    elif ptype == "pkg":
        # XAR package magic used by Apple installer packages.
        if header[:4] != b"xar!":
            raise RuntimeError("INSTALLER_ARTIFACT_PKG_MAGIC_INVALID")
    else:
        raise RuntimeError(f"INSTALLER_ARTIFACT_TYPE_UNSUPPORTED:{ptype}")

    return {
        "status": STATUS_PASS,
        "artifact_sha256": _sha256(artifact),
        "size_bytes": size,
        "package_type": ptype,
        "agent_version": str(expected_version),
        "payload_contract_sha256": str(expected_contract_sha256),
        "embedded_contract_verified": embedded_contract if ptype in {"tar.gz", "deb", "exe"} else "prepackage-verified",
    }


def refresh_installer_contract(payload: Path, *, extra_required: Iterable[str]) -> dict[str, Any]:
    """Refresh an already-created payload contract after platform build additions.

    Windows uses this after compiling GIDEONAgentServiceHost.exe but before the EXE
    backend enumerates payload files.  The updated contract therefore travels
    inside the final installer.
    """
    payload = Path(payload).resolve()
    current = _json(payload / "installer.contract.json")
    # A platform packager may add a native helper after the catalog has staged
    # target-specific files (for example the signed offline VLC kit).  Preserve
    # the original required set while adding its helper; otherwise the refresh
    # would silently drop previously verified hashes from the final EXE.
    prior_required = [str(item) for item in current.get("required_files") or []]
    return write_installer_contract(
        payload,
        target_id=str(current.get("target_id") or ""),
        platform_name=str(current.get("platform") or ""),
        architecture=str(current.get("architecture") or ""),
        version=str(current.get("agent_version") or ""),
        package_type=str(current.get("package_type") or ""),
        extra_required=tuple(prior_required) + tuple(extra_required),
    )
